NAME = 'UkrOgienko: Українська Біблія. Переклад Івана Огієнка.'
BOOK = 'Malachi'

CHAPTERS = {
    1: {
        1: 'Пророцтво Господнього слова до Ізраїля через Малахі́ю.',
        2: '„Я вас полюбив, — говорить Госпо́дь, — а ви кажете: „Як Ти нас полюбив?“Чи ж не брат Іса́в Якову? каже Госпо́дь, а Я Якова був полюбив,',
        3: 'а Іса́ва знена́видів, і зробив його гори спусто́шенням, а спа́док його — для шака́лів пустині.',
        4: 'Коли скаже Едо́м: „Ми зруйно́вані, та зно́ву збуду́ємо руїни“, то так промовляє Госпо́дь Савао́т: Вони побуду́ють, а Я розвалю́! І звати їх будуть: Країна безбо́жности, і наро́д, на якого навіки розгні́вавсь Господь!',
        5: 'І ваші очі побачать оце, і ви скажете: Стане великий Госпо́дь понад границю Ізраїлеву!',
        6: 'Шанує син ба́тька, а раб — свого пана; та якщо Я вам ба́тько, де пошана Моя? А якщо Я вам пан, де страх передо Мною? говорить Господь Савао́т вам, священики, що пого́рджуєте Моїм Іме́нням та й кажете: „Чим ми погорди́ли Йме́нням Твоїм?“',
        7: 'На же́ртівник Мій ви прино́сите хліб занечи́щений і кажете: „Чим Тебе ми знева́жили?“Тим, що кажете ви: „Трапе́за Господня — вона пого́рджена!“',
        8: 'І коли ви прино́сите в жертву сліпе́, це не зле? І як кульга́ве та хворе прино́сите, чи ж це не зле? Принеси но поді́бне своє́му намі́сникові, чи тебе він вподо́бає, чи піді́йме обличчя твоє? промовляє Госпо́дь Савао́т.',
        9: 'А тепер ублага́йте ви Боже лице, і хай стане для нас милости́вим, з ваших рук це було́, то хіба кому з вас Він обличчя піді́йме? говорить Господь Саваот.',
        10: 'Нехай хто серед вас замкне двері святині, і не бу́де нада́рмо освічувати Мого же́ртівника! Я не маю вподо́би до вас, говорить Господь Савао́т, і з ваших рук не вподо́баю да́ру!',
        11: 'Бо від сходу сонця й аж по за́хід його́ звеличи́ться Йме́ння Моє між наро́дами, і ка́диться в кожному місці для Ймення Мого дар чистий, бо звели́читься Ймення Моє між наро́дами, каже Госпо́дь Савао́т.',
        12: 'Ви ж Його зневажа́єте, ка́жучи: „Трапе́за Господня — вона занечи́щена, й дохід її, обри́джена страва її“.',
        13: 'І до того говорите: „Ось стільки пра́ці!“і ним нехтуєте, — говорить Госпо́дь Савао́т, — і прино́сите кра́дене, і кульга́ве та хворе, і таку жертву хлібну прино́сите. Чи буде воно Мені миле з рук ваших? говорить Госпо́дь.',
        14: 'І прокля́тий обма́нець, що в ста́ді його є саме́ць, а він обіцяє та в жертву дає Господе́ві зіпсуте, А Я Цар великий, — говорить Госпо́дь, — і серед наро́дів грізне́ Моє Ймення!',
    },
    2: {
        1: 'А тепер до вас за́повідь цяя, священики!',
        2: 'Якщо ви не послу́хаєтесь, і не покладе́те на серце собі, щоб Іме́нню Моєму давати хвалу́, — говорить Госпо́дь Савао́т, — то пошлю Я прокля́ття на вас, і прокляну́ благословення ваші, і вже проклина́ю, бо ви не бере́те до серця цього́!',
        3: 'Ось Я обітну́ вам раме́но, і розпоро́шу нечистість на ваших обли́ччях, нечистість свят ваших, і до неї вас ви́несуть.',
        4: 'І пізнаєте ви, що Я заповідь вам цю послав, щоб був заповіт Мій з Леві́єм, каже Госпо́дь Савао́т.',
        5: 'Заповіт Мій з ним був для життя та для миру, і Я дав йому страх, і він налякався Мене, та боя́всь перед Іме́нням Моїм.',
        6: 'Закон правди в уста́х його був, і не знайшла́сь на губа́х його кривда, — у мирі й просто́ті ходив він зо Мною, і багато-кого́ відверну́в від вини.',
        7: 'Бо у́ста священикові знання́ стережу́ть та Зако́на шукають із уст його, бо він ангол Господа Саваота.',
        8: 'А ви відхили́лись з дороги, вчини́ли таке, що багато спіткну́лись в Зако́ні, Леві́євого заповіта пони́щили, говорить Госпо́дь Савао́т.',
        9: 'Тому́ то і Я вас зробив пого́рджуваними й низьки́ми для всього наро́ду, бо не стереже́те доріг Моїх ви, та не безсторо́нні в Зако́ні.',
        10: 'Чи Оте́ць нам усім не оди́н? Хіба Бог не один нас створи́в? Чому́ ж один о́дного зраджуємо ми, щоб нам зневажа́ти запові́т батькі́в наших?',
        11: 'Зраджує Юда, і робиться не́чисть серед Ізраїля та в Єрусалимі, — бо Юда зневажив святиню Господню, яку покохав був, і дочку бога чужого за жінку узя́в.',
        12: 'Нехай Господь ви́губить кожного, хто́ таке робить, того, хто чува́є та відповідає з наме́тів Якова, і хто да́р прино́сить Господу Саваоту.',
        13: 'І робите й друге таке: Господнього же́ртівника ви слізьми́ покриваєте, плаче́м та стогна́нням, бо до да́рів уже Він не зве́рнеться більше, і милої жертви з рук ваших не ві́зьме.',
        14: 'А ви ще й говорите: „За́що?“— За те, що засві́дчив Господь між тобою й жоною юна́цтва твого́, якій ти невірність вчинив, а вона ж твоя по́друга, і дружи́на умо́ви твоєї!',
        15: 'Хіба Бог не один нас учинив? І за́лишок духу — Його́. А що цей один? Насіння від Бога шукав. Тому́ свого духа пильну́йте, і дружи́ну юна́цтва свойо́го не зраджуйте!',
        16: 'Бо нена́виджу ро́звід, — говорить Госпо́дь, Бог Ізраїлів, — і того, хто вкриває наси́льством одежу свою, промовляє Госпо́дь Савао́т. Тому́ свого духа пильнуйте, — і не зраджу́йте!',
        17: 'Словами своїми ви мучите Господа, та й пита́єте ще: „Чим ми мучимо?“— Гово́ренням вашим: „Кожен, хто чинить ли́хе, той добрий у Господніх оча́х, і Він у них уподо́бання має“, або: „Де Бог правосу́ддя?“',
    },
    3: {
        1: 'Ось Я посилаю Свого ангола, і він перед обличчям Моїм приготу́є доро́гу. І на́гло прибу́де до храму Свого Госпо́дь, Якого шукаєте ви, і Ангол запові́ту, Якого жада́єте. Ось іде Він, говорить Господь Саваот!',
        2: "І хто ви́терпить день Його прибуття́, і хто всто́їть, коли Він з'я́виться? Бо Він, як огонь той у золотаря́, і як у пра́льників луг.",
        3: 'І Він сяде топи́ти та чи́стити срі́бло, і очи́стить синів Леві́я, і їх перечи́стить, як золото й срі́бло, і будуть для Господа жертву прино́сити в правді.',
        4: 'Тоді бу́де дар Юди та Єрусалиму приє́мний для Господа, як за днів вікові́чних і за років старода́вніх.',
        5: 'І прибу́ду до вас Я на суд, і буду сві́дком швидки́м проти чарівників, і на перелю́бників, і проти тих, хто прися́гу складає на лжу, і проти тих, хто запла́тою на́ймита тисне, вдову́ й сироту́, хто відхилює право чужи́нця, Мене ж не боїться, говорить Госпо́дь Савао́т.',
        6: 'Бо Я, Господь, не змі́нююся, тому ви, сини Яковові, не будете зни́щені.',
        7: 'Від уста́в Моїх ви відступили́ з днів ваших батькі́в, і їх не стерегли́. Верніться ж до Мене, і верну́сь Я до вас! промовляє Господь Савао́т. Та говорите ви: „У чо́му пове́рнемось?“',
        8: 'Чи Бога люди́на обманить? Мене ж ви обма́нюєте, ще й говорите: „Чи́м ми Тебе обмани́ли?“— Десяти́ною та прино́сами!',
        9: 'Прокля́ттям ви про́кляті, а Мене обмани́ли, о люду ти ввесь!',
        10: 'Принесіть же ви всю десяти́ну до дому скарбни́ці, щоб стра́ва була́ в Моїм храмі, і тим Мене ви́пробуйте, — промовляє Господь Саваот: чи небесних отво́рів вам не відчиню́, та не ви́ллю вам благослове́ння аж на́дмір?',
        11: "І ради вас насварю́ Я все те, що жере́, і воно не пони́щить вам зе́много пло́ду, і не заб'є винограду вам на по́лі, говорить Господь Саваот.",
        12: 'І будуть всі люди вважати вас блаже́нними, бо бу́дете ви любим кра́єм, говорить Господь Саваот.',
        13: 'Жорстокі ваші слова́ проти Мене, — говорить Госпо́дь, — а ви кажете: „Що́ ми на Тебе сказали?“',
        14: 'Ви кажете: „Ма́рність служити для Бога! І що за ко́ристь, що ми стереже́мо Його службу, та ходимо в жало́бі перед лицем Господа Саваота?',
        15: 'А тепер ми вважаємо пи́шних щасли́вими, і ті, хто вчиня́є безбожне, буду́ються та випробо́вують Бога, і втікають“.',
        16: "Змовлялись тоді один з о́дним і ті, хто стра́х перед Го́сподом має, — і прислу́хавсь Господь, і почув, і перед обличчям Його була пи́сана па́м'ятна книга про тих, хто стра́х перед Го́сподом має, і хто поважає Йме́ння Його.",
        17: 'І бу́дуть Мені вони вла́сністю, — каже Господь Савао́т, — на той день, що вчиню́, і змилосе́рджусь над ними, як змилосе́рджується чоловік над синами своїми, що служать йому.',
        18: 'І ви зно́ву побачите різницю́ між пра́ведним та нечести́вим, між тим, хто Бо́гові служить, та тим, хто не служить Йому́.',
    },
    4: {
        1: 'Бо ось наступає той день, що пала́є, як піч, і стануть всі пи́шні та кожен, хто чинить безбо́жне, соломою, — і спа́лить їх день той, який наступа́є, говорить Госпо́дь Савао́т, Який не позоста́вить їм ко́реня, ані галу́зки.',
        2: 'А для вас, хто Йме́ння Мойо́го боїться, зійде Сонце Праведности та лікува́ння в промінях Його, — і ви ви́йдете та поскака́єте, мов ті си́ті теля́та!',
        3: "І безбожних топтати ви будете, бо стануть за по́піл вони під п'ята́ми ніг ваших у той день, що його Я вчиню́, промовляє Госпо́дь Савао́т.",
        4: 'Згадайте Зако́на Мойсея, Мого раба́, що йому́ наказав на Хори́ві уста́ви й права́ щодо всьо́го Ізраїля.',
        5: 'Ось Я пошлю́ вам пророка Іллю́, перше ніж день Госпо́дній наста́не, великий й страшни́й!',
        6: 'І приве́рне він серце батькі́в до сині́в, і серце сині́вське до їхніх батькі́в, щоб Я не прийшов, і не вра́зив цей край прокля́ттям!',
    },
}
